edits:
/* V52: information density within the accepted scene, not another visual theme. */
.hero-context{font-size:15px;line-height:1.75;color:var(--muted);max-width:590px;margin-top:18px}.hero-benefits{list-style:none;display:flex;gap:20px 40px;flex-wrap:wrap;padding:24px 0 28px;margin:auto 0 0;font-size:13px;color:var(--mint)}.hero-benefits li{display:flex;gap:10px;align-items:center}.hero-benefits li:before{content:'';width:4px;height:4px;background:currentColor;border-radius:50%;flex:none}.hero{min-height:min(750px,calc(100svh - 82px))}.hero-type{padding-top:clamp(42px,7vh,88px);padding-bottom:34px;max-width:960px}.hero-intro{max-width:650px}.hero-type h1{font-size:clamp(64px,6.5vw,100px)}
.chapter-explanations{display:grid;gap:18px;margin:24px 0 0}.chapter-explanations div{display:grid;grid-template-columns:100px minmax(0,1fr);gap:18px;font-size:14px;line-height:1.75}.chapter-explanations dt{color:var(--mint)}.chapter-explanations dd{margin:0;color:var(--muted)}.experience-stage{min-height:0;align-items:center}.experience-story{padding-block:16px 22px}.section-heading{gap:6%;margin-bottom:30px}.section-space{padding-block:52px}.experience-disclosure{margin-top:12px}
.control-summary .section-heading h2{font-size:clamp(32px,3vw,48px)}.responsibility-columns{display:grid;grid-template-columns:1fr 1fr;gap:10%;margin-top:32px}.responsibility-columns h3{font-size:23px;color:var(--mint)}.responsibility-columns dl{display:grid;gap:22px;margin:22px 0 0}.responsibility-columns dt{font-size:17px;color:var(--ink);margin-bottom:7px}.responsibility-columns dd{font-size:15px;line-height:1.8;color:var(--muted);margin:0;max-width:570px}.control-boundary{display:flex;gap:40px;justify-content:space-between;align-items:center;margin-top:32px}.control-boundary>p{font-size:14px;max-width:680px}.control-boundary .text-link{flex-shrink:0}
.status-section{gap:32px 8%}.evidence-links{grid-column:1/-1;padding-top:16px}.evidence-links>header{max-width:940px}.evidence-links h3{font-size:29px;margin:16px 0}.evidence-links>header>p:not(.eyebrow){font-size:15px;max-width:830px}.evidence-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-top:28px}.evidence-grid h4{margin:0 0 13px;font-size:19px;font-weight:500}.evidence-grid p{font-size:14px;line-height:1.8}.evidence-grid .evidence-limit{font-size:12px;color:var(--quiet);margin-top:12px}.evidence-next{margin-top:20px}.evidence-next strong{display:block;font:10px/1.7 ui-monospace,monospace;letter-spacing:.1em;color:var(--mint);margin-bottom:7px}.evidence-links>.text-link{margin-top:18px}
.radar-other-notes{grid-column:1/-1}.radar-other-notes>div{display:grid;grid-template-columns:1fr 1fr;gap:38px;margin:18px 0}.radar-other-notes article>a{display:block;font-size:19px;line-height:1.4;max-width:530px}.radar-other-notes time{display:block;font:10px ui-monospace,monospace;color:var(--quiet);margin-top:10px}.radar-other-notes>p:last-child{font-size:12px;max-width:800px;color:var(--quiet)}.radar-teaser{row-gap:26px}.community{padding-block:52px}.contributor-start{margin-top:18px;font-size:13px;color:var(--quiet)}
.product-overview{padding-block:12px 54px}.product-overview h2{font-size:clamp(32px,3.4vw,50px);margin-top:18px}.overview-intro{margin-top:18px;max-width:820px;font-size:15px}.architecture-parts{display:grid;grid-template-columns:1fr 1fr;gap:36px 7%;margin-top:30px}.architecture-parts article>span{font:11px ui-monospace,monospace;color:var(--mint)}.architecture-parts h3{font-size:26px;margin:15px 0}.architecture-parts p{font-size:15px;max-width:600px}.ai-boundary{margin-top:36px;max-width:890px}.ai-boundary h3{font-size:27px}.ai-boundary p{font-size:15px;margin-top:16px}.document-hero{padding-block:48px 42px}.product-document{padding-bottom:62px}
@media(min-width:1800px){.wrap,.section-shell{width:min(100%,1712px)}.hero-type{max-width:1050px}.hero-type h1{font-size:108px}.hero-intro{font-size:19px;max-width:720px}.hero-context{font-size:16px;max-width:690px}.hero-benefits{font-size:15px}.experience-story>p{font-size:17px;max-width:640px}.chapter-explanations div{font-size:16px}.responsibility-columns dd,.architecture-parts p{font-size:17px}.evidence-grid p{font-size:16px}}
@media(max-width:850px){.control-boundary{display:block}.control-boundary>.text-link{margin-top:14px}.evidence-grid{gap:30px}.chapter-explanations div{grid-template-columns:1fr;gap:4px}}
@media(max-width:760px){.section-space{padding-block:26px}.hero{min-height:0}.hero-type{padding-top:38px;padding-bottom:18px}.hero-type h1{font-size:clamp(47px,12vw,74px)}.hero-context{font-size:14px;margin-top:14px}.hero-benefits{display:grid;gap:12px;padding:20px 0 28px;font-size:12px}.hero-actions{margin-top:22px}.chapter-explanations{gap:14px;margin-top:20px}.chapter-explanations div{font-size:14px;grid-template-columns:1fr;gap:3px}.section-heading{margin-bottom:20px}.experience-art{height:302px;min-height:302px}.experience-story{padding-top:14px}.experience-disclosure{margin:12px 0 0}.responsibility-columns{grid-template-columns:1fr;gap:28px;margin-top:25px}.responsibility-columns h3{font-size:22px}.responsibility-columns dl{margin-top:16px;gap:18px}.responsibility-columns dd{font-size:14px}.control-boundary{margin-top:25px}.control-boundary p{font-size:13px}.status-section{gap:22px}.status-card{padding-bottom:0}.evidence-links{padding-top:8px}.evidence-links h3{font-size:26px}.evidence-grid{grid-template-columns:1fr;gap:26px;margin-top:22px}.evidence-grid h4{font-size:18px}.radar-other-notes>div{grid-template-columns:1fr;gap:22px}.radar-other-notes article>a{font-size:18px}.community{padding-block:30px}.contributor-start{font-size:12px}.product-overview{padding-block:0 36px}.architecture-parts{grid-template-columns:1fr;gap:24px;margin-top:24px}.architecture-parts h3{font-size:24px}.architecture-parts p{font-size:14px}.ai-boundary{margin-top:28px}.document-hero{padding-block:35px 32px}.product-document{padding-bottom:45px}}
